package com.stocksense.product; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; @Entity @Getter @Setter @NoArgsConstructor public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false,unique=true) private String sku; @ManyToOne private Category category; @Column(nullable=false) private String unitOfMeasure="PCS"; @Column(nullable=false) private BigDecimal minimumStock=BigDecimal.ZERO; @Column(nullable=false) private BigDecimal reorderQuantity=BigDecimal.ZERO; private String barcode; private boolean active=true; }
